using UnityEngine;

namespace FlyingRush.Game
{
    /// <summary>
    /// Every material and sound the game uses, generated by the project builder
    /// (Assets/Editor/ProjectBuilder.cs) and tools/audio.
    /// </summary>
    [CreateAssetMenu(menuName = "Flying Rush/Game Art")]
    public sealed class GameArt : ScriptableObject
    {
        [Header("Map")]
        public Material Floor;
        public Material Wall;
        public Material Concrete;
        public Material Metal;
        public Material[] Containers;
        public Material Neon;
        public Material Teal;
        public Material Grid;
        public Material Pad;
        public Material Sky;

        [Header("Fighters and effects")]
        public Material Fighter;
        public Material Visor;
        public Material Gun;
        public Material Tracer;
        public Material Glow;
        public Material Spark;

        [Header("Weapons")]
        public AudioClip Rifle;
        public AudioClip Shotgun;
        public AudioClip Sniper;
        public AudioClip RocketFire;
        public AudioClip Explosion;
        public AudioClip Railgun;
        public AudioClip Reload;
        public AudioClip Empty;
        public AudioClip Switch;
        public AudioClip Pickup;

        [Header("Fighters")]
        public AudioClip Jump;
        public AudioClip AirJump;
        public AudioClip Land;
        public AudioClip Hit;
        public AudioClip Headshot;
        public AudioClip Kill;
        public AudioClip Hurt;
        public AudioClip Death;

        [Header("Match and menus")]
        public AudioClip Countdown;
        public AudioClip Go;
        public AudioClip Streak;
        public AudioClip Win;
        public AudioClip Lose;
        public AudioClip Move;
        public AudioClip Select;
        public AudioClip Pause;
        public AudioClip TitleMusic;
        public AudioClip BattleMusic;
    }
}
